        // Methods.
        public async Task<decimal> GetBzzPriceInUsdcAsync(CancellationToken cancellationToken = default) =>
            await GetBzzPriceInEtherAsync(cancellationToken).ConfigureAwait(false) *
            await GetEtherPriceInUsdcAsync(cancellationToken).ConfigureAwait(false);

        public Task<decimal> GetBzzPriceInEtherAsync(CancellationToken cancellationToken = default) =>
            ReadPriceFromV3PoolAsync(BzzEthPoolAddress, BzzDecimals, EthDecimals);

        public async Task<decimal> GetEtherPriceInUsdcAsync(CancellationToken cancellationToken = default) =>
            1 / await ReadPriceFromV3PoolAsync(UsdcEthPoolAddress, UsdcDecimals, EthDecimals).ConfigureAwait(false);
        
        // Helpers.
        private async Task<decimal> ReadPriceFromV3PoolAsync(
            string poolAddress,
            int token0Decimals,
            int token1Decimals)
        {
            var contract = web3.Eth.GetContract(UniswapV3Abi, poolAddress);
            var slot0Function = contract.GetFunction("slot0");
            var slot0Result = await slot0Function.CallDeserializingToObjectAsync<Slot0OutputDto>().ConfigureAwait(false);
        
            // Convert sqrtPriceX96 in price.
            //price = (sqrtPriceX96 / 2^96)^2 * (10^token0Decimals / 10^token1Decimals)
            var q96 = BigInteger.Pow(2, 96);
            var sqrtPrice = (double)slot0Result.SqrtPriceX96 / (double)q96;
            var price = Math.Pow(sqrtPrice, 2);
    
            // Decimals adjustment.
            price *= Math.Pow(10, token0Decimals - token1Decimals);
    
            return (decimal)price;
        }
    }
